package br.com.minhadieta.app;import android.content.*;import android.app.*;import android.graphics.Color;public class MealReceiver extends BroadcastReceiver{public void onReceive(Context c,Intent i){String n=i.getStringExtra("name");int id=i.getIntExtra("id",1);Intent open=new Intent(c,MainActivity.class);PendingIntent p=PendingIntent.getActivity(c,id,open,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification.Builder b=new Notification.Builder(c,"meals").setSmallIcon(R.drawable.ic_launcher).setContentTitle("Hora de comer").setContentText(n+" — veja o que está no seu plano.").setAutoCancel(true).setContentIntent(p);((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify(id,b.build());}}